//! BWAPI type tables (013-R1): unit / tech / upgrade / weapon data generated by
//! `tools/bwapi-tables`. Feature normalisation (030), capability masks and prerequisites
//! (034-R3) and the executor (031) read them instead of hard-coded ids.

use std::sync::OnceLock;

use anyhow::Result;
use serde::Deserialize;

pub const UNIT_TYPES_TOML: &str = include_str!("../tables/unit_types.toml");
pub const TECH_TYPES_TOML: &str = include_str!("../tables/tech_types.toml");
pub const UPGRADE_TYPES_TOML: &str = include_str!("../tables/upgrade_types.toml");
pub const WEAPON_TYPES_TOML: &str = include_str!("../tables/weapon_types.toml");
pub const ORDER_TYPES_TOML: &str = include_str!("../tables/order_types.toml");

#[derive(Deserialize)]
struct OrderRow {
    id: u16,
    name: String,
}

/// BWAPI order id by name (`tables/order_types.toml`).
pub fn order_id(name: &str) -> Option<u16> {
    static O: OnceLock<Vec<OrderRow>> = OnceLock::new();
    O.get_or_init(|| toml::from_str::<Rows<OrderRow>>(ORDER_TYPES_TOML).expect("order table").rows).iter().find(|o| o.name == name).map(|o| o.id)
}

/// BWAPI `UnitPrototypeFlags` names used here.
pub mod flag {
    pub const BUILDING: &str = "Building";
    pub const ADDON: &str = "Addon";
    pub const FLYER: &str = "Flyer";
    pub const WORKER: &str = "Worker";
    pub const SUBUNIT: &str = "Subunit";
    pub const FLYING_BUILDING: &str = "FlyingBuilding";
    pub const HERO: &str = "Hero";
    pub const RESOURCE_DEPOT: &str = "ResourceDepot";
    pub const RESOURCE_CONTAINER: &str = "ResourceContainer";
    pub const DETECTOR: &str = "Detector";
    pub const ORGANIC: &str = "OrganicUnit";
    pub const SPELLCASTER: &str = "Spellcaster";
    pub const ATTACK: &str = "Attack";
    pub const INVINCIBLE: &str = "Invincible";
    pub const MECHANICAL: &str = "Mechanical";
    pub const PRODUCES_UNITS: &str = "ProducesUnits";
}

#[derive(Deserialize, Debug, Clone)]
pub struct UnitType {
    pub id: i32,
    pub name: String,
    pub race: String,
    pub flags: Vec<String>,
    pub max_hp: i32,
    pub max_shields: i32,
    pub max_energy: i32,
    pub armor: i32,
    pub minerals: i32,
    pub gas: i32,
    pub build_time: i32,
    pub supply_provided: i32,
    pub supply_required: i32,
    pub space_required: i32,
    pub space_provided: i32,
    pub tile_width: i32,
    pub tile_height: i32,
    pub dimensions: [i32; 4],
    pub what_builds: i32,
    pub required_units: Vec<[i32; 2]>,
    pub required_tech: i32,
    pub sight_range: i32,
    pub ground_weapon: i32,
    pub air_weapon: i32,
    pub size: String,
    pub top_speed: f64,
}

impl UnitType {
    pub fn has(&self, flag: &str) -> bool {
        self.flags.iter().any(|f| f == flag)
    }
    pub fn is_building(&self) -> bool {
        self.has(flag::BUILDING)
    }
    pub fn is_addon(&self) -> bool {
        self.has(flag::ADDON)
    }
    pub fn is_worker(&self) -> bool {
        self.has(flag::WORKER)
    }
    pub fn is_flyer(&self) -> bool {
        self.has(flag::FLYER)
    }
    pub fn is_mechanical(&self) -> bool {
        self.has(flag::MECHANICAL)
    }
    pub fn is_organic(&self) -> bool {
        self.has(flag::ORGANIC)
    }
    pub fn is_resource(&self) -> bool {
        self.has(flag::RESOURCE_CONTAINER)
    }
    pub fn is_playable(&self) -> bool {
        matches!(self.race.as_str(), "Terran" | "Zerg" | "Protoss") && !self.has(flag::HERO) && !self.has(flag::SUBUNIT)
    }
}

#[derive(Deserialize, Debug, Clone)]
pub struct TechType {
    pub id: i32,
    pub name: String,
    pub race: String,
    pub minerals: i32,
    pub gas: i32,
    pub research_time: i32,
    pub energy: i32,
    pub what_researches: i32,
    pub required_unit: i32,
    pub targets_unit: bool,
    pub targets_position: bool,
}

#[derive(Deserialize, Debug, Clone)]
pub struct UpgradeType {
    pub id: i32,
    pub name: String,
    pub race: String,
    pub minerals_base: i32,
    pub minerals_factor: i32,
    pub gas_base: i32,
    pub gas_factor: i32,
    pub time_base: i32,
    pub time_factor: i32,
    pub max_repeats: i32,
    pub what_upgrades: i32,
    pub required_units: [i32; 3],
}

impl UpgradeType {
    /// Cost of researching `level` (1-based), BWAPI `mineralPrice(level)`.
    pub fn minerals(&self, level: i32) -> i32 {
        self.minerals_base + (level - 1).max(0) * self.minerals_factor
    }
    pub fn gas(&self, level: i32) -> i32 {
        self.gas_base + (level - 1).max(0) * self.gas_factor
    }
}

#[derive(Deserialize, Debug, Clone)]
pub struct WeaponType {
    pub id: i32,
    pub name: String,
    pub damage: i32,
    pub damage_bonus: i32,
    pub cooldown: i32,
    pub min_range: i32,
    pub max_range: i32,
}

#[derive(Deserialize)]
struct Rows<T> {
    rows: Vec<T>,
}

#[derive(Debug, Clone)]
pub struct TypeTables {
    pub units: Vec<UnitType>,
    pub techs: Vec<TechType>,
    pub upgrades: Vec<UpgradeType>,
    pub weapons: Vec<WeaponType>,
}

impl TypeTables {
    pub fn parse() -> Result<Self> {
        Ok(Self {
            units: toml::from_str::<Rows<UnitType>>(UNIT_TYPES_TOML)?.rows,
            techs: toml::from_str::<Rows<TechType>>(TECH_TYPES_TOML)?.rows,
            upgrades: toml::from_str::<Rows<UpgradeType>>(UPGRADE_TYPES_TOML)?.rows,
            weapons: toml::from_str::<Rows<WeaponType>>(WEAPON_TYPES_TOML)?.rows,
        })
    }

    /// Shared parsed copy (the tables are compiled in).
    pub fn get() -> &'static TypeTables {
        static T: OnceLock<TypeTables> = OnceLock::new();
        T.get_or_init(|| Self::parse().expect("compiled-in BWAPI type tables parse"))
    }

    pub fn unit(&self, id: u16) -> Option<&UnitType> {
        self.units.get(id as usize)
    }

    pub fn unit_by_name(&self, name: &str) -> Option<&UnitType> {
        self.units.iter().find(|u| u.name == name)
    }

    pub fn weapon(&self, id: i32) -> Option<&WeaponType> {
        (id >= 0).then(|| self.weapons.get(id as usize)).flatten()
    }

    /// Terran unit and building types the agent can own (030 §4 own counts, §5 z_units).
    pub fn terran_subset(&self) -> Vec<u16> {
        self.units.iter().filter(|u| u.race == "Terran" && u.is_playable() && u.name != "Terran_Civilian").map(|u| u.id as u16).collect()
    }

    /// Playable unit and building types of every race (030 §4 observed enemy maxima).
    pub fn all_races_subset(&self) -> Vec<u16> {
        self.units
            .iter()
            .filter(|u| u.is_playable() && u.name != "Terran_Civilian" && !u.name.starts_with("Zerg_Broodling"))
            .map(|u| u.id as u16)
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_load_with_bwapi_counts_013_r1() {
        let t = TypeTables::get();
        assert_eq!((t.units.len(), t.techs.len(), t.upgrades.len(), t.weapons.len()), (234, 47, 63, 132));
        let scv = t.unit(7).unwrap();
        assert_eq!((scv.name.as_str(), scv.minerals, scv.build_time, scv.supply_required), ("Terran_SCV", 50, 300, 2));
        assert!(scv.is_worker() && scv.is_mechanical() && scv.is_organic());
        let rax = t.unit_by_name("Terran_Barracks").unwrap();
        assert_eq!((rax.tile_width, rax.tile_height), (4, 3));
        assert!(rax.required_units.contains(&[106, 1]));
        assert_eq!(t.techs[0].name, "Stim_Packs");
        assert_eq!(t.weapon(t.unit(0).unwrap().ground_weapon).unwrap().cooldown, 15);
    }
}
